INSERT INTO `village_officials` (`id`, `nama`, `jabatan`, `kategori`, `foto`, `pendidikan`, `masa_jabatan`, `kontak`, `tugas`, `sort_order`, `is_active`, `show_on_home`, `created_at`, `updated_at`, `deleted_at`) VALUES
(7, 'H. Mahmud Yunus', 'Ketua BPD', 'bpd', NULL, 'S1', '2019 - 2025', NULL, 'Mengawasi kinerja pemerintah desa dan menampung aspirasi masyarakat.', 7, 1, 0, '2026-07-08 22:07:33', '2026-07-09 01:56:49', '2026-07-09 01:56:49'),
(8, 'Euis Komariah', 'Ketua TP PKK', 'pkk', NULL, 'SMA', '2021 - 2027', NULL, 'Menggerakkan pemberdayaan kesejahteraan keluarga di tingkat desa.', 8, 1, 0, '2026-07-08 22:07:33', '2026-07-09 01:57:18', '2026-07-09 01:57:18'),
(9, 'Rian Ardiansyah', 'Ketua Karang Taruna', 'karang_taruna', NULL, 'SMA', '2022 - 2025', NULL, 'Menggerakkan kepemudaan, olahraga, dan kegiatan sosial pemuda desa.', 9, 1, 0, '2026-07-08 22:07:33', '2026-07-09 01:57:48', '2026-07-09 01:57:48'),
(32, 'PAIMIN', 'Lurah', 'pemerintah', 'protected/officials/20260709-b9a7ae3a3adaa269.png', NULL, NULL, NULL, 'Memimpin penyelenggaraan pemerintahan desa/kelurahan, pembangunan, pembinaan kemasyarakatan, pemberdayaan masyarakat, pelayanan publik, serta koordinasi perangkat desa.', 1, 1, 1, '2026-07-09 01:54:12', '2026-07-09 02:09:37', NULL),
(33, 'AGUNG RAHARJO, SE', 'Sekretaris', 'pemerintah', 'protected/officials/20260709-fadf16387967208b.png', NULL, NULL, NULL, 'Membantu Lurah dalam penyelenggaraan administrasi pemerintahan desa, pengoordinasian perangkat desa, surat menyurat, tata usaha, pelaporan, dan pelayanan administrasi desa.', 2, 1, 1, '2026-07-09 01:54:12', '2026-07-09 02:09:54', NULL),
(34, 'Sri Handayani', 'Kasi Pemerintahan', 'pemerintah', 'protected/officials/20260709-235c33d8dc76d579.png', NULL, NULL, NULL, 'Melaksanakan urusan pemerintahan desa, administrasi kependudukan, pertanahan, ketertiban, perlindungan masyarakat, serta pembinaan tata kelola pemerintahan di tingkat desa.', 3, 1, 1, '2026-07-09 01:54:12', '2026-07-09 02:10:20', NULL),
(35, 'DIDIK ZAINUDIN, S.Si', 'Kasi Kesejahteraan', 'pemerintah', 'protected/officials/20260709-4e4fd6d491cf955d.png', NULL, NULL, NULL, 'Melaksanakan program kesejahteraan masyarakat, pembangunan, pemberdayaan masyarakat, pembinaan sosial, serta fasilitasi kegiatan kesehatan, pendidikan, dan sosial kemasyarakatan.', 4, 1, 1, '2026-07-09 01:54:12', '2026-07-09 02:10:41', NULL),
(36, 'Sumarno, SH', 'Kasi Pelayanan', 'pemerintah', 'protected/officials/20260709-c0e9124041208ce4.png', NULL, NULL, NULL, 'Melaksanakan pelayanan administrasi masyarakat, fasilitasi layanan publik, penyuluhan, serta peningkatan kualitas pelayanan kepada warga desa.', 5, 1, 1, '2026-07-09 01:54:12', '2026-07-09 02:11:12', NULL),
(37, 'Biony Akbar Tata Nugraha, A.Md.Kom', 'Kaur Perencanaan', 'pemerintah', 'protected/officials/20260709-e6322c323bf89df6.png', NULL, NULL, NULL, 'Melaksanakan penyusunan perencanaan pembangunan desa, pengendalian program, penyusunan RPJMDes, RKPDes, pelaporan kegiatan, dan evaluasi program desa.', 6, 1, 0, '2026-07-09 01:54:12', '2026-07-09 02:12:45', NULL),
(38, 'Fadillatul Nur Kasanah, S.Pd', 'Kaur Tata Usaha dan Umum', 'pemerintah', 'protected/officials/20260709-80296164e5c70c4e.png', NULL, NULL, NULL, 'Melaksanakan urusan ketatausahaan, surat menyurat, arsip, inventaris, administrasi perangkat desa, pengelolaan aset, dan pelayanan administrasi umum.', 7, 1, 0, '2026-07-09 01:54:12', '2026-07-09 02:14:13', NULL),
(39, 'Erwin Susanti, A.Md', 'Kaur Keuangan', 'pemerintah', 'protected/officials/20260709-da6231fe7817c550.png', NULL, NULL, NULL, 'Melaksanakan administrasi keuangan desa, pembukuan, penatausahaan APBDes, pengelolaan pendapatan dan belanja desa, serta penyusunan laporan keuangan desa.', 8, 1, 0, '2026-07-09 01:54:12', '2026-07-09 02:14:46', NULL),
(40, 'Eka Susanti', 'Kebayanan Garut 1', 'pemerintah', 'protected/officials/20260709-f55258ceecee0286.png', NULL, NULL, NULL, 'Membantu pelaksanaan tugas pemerintahan desa di wilayah Kebayanan Garut 1, termasuk koordinasi warga, penyampaian informasi desa, dan fasilitasi pelayanan masyarakat.', 9, 1, 0, '2026-07-09 01:54:12', '2026-07-09 02:15:58', NULL),
(41, 'Parlan', 'Kebayanan Daren', 'pemerintah', 'protected/officials/20260709-b752ac3e7fae66e7.png', NULL, NULL, NULL, 'Membantu pelaksanaan tugas pemerintahan desa di wilayah Kebayanan Daren, termasuk koordinasi warga, penyampaian informasi desa, dan fasilitasi pelayanan masyarakat.', 10, 1, 0, '2026-07-09 01:54:12', '2026-07-09 02:16:15', NULL),
(42, 'DIDIK ZAINUDIN, S.Si', 'PJ Garut 2', 'pemerintah', '1744664619864545.jpg', NULL, NULL, NULL, 'Pejabat penanggung jawab wilayah Garut 2. Status kehadiran pada data lama: Belum Rekam Kehadiran.', 11, 1, 0, '2026-07-09 01:54:12', '2026-07-09 01:54:12', NULL),
(43, 'SUMARNO, SH', 'PJ Dawung', 'pemerintah', '174466472829635.jpg', NULL, NULL, NULL, 'Pejabat penanggung jawab wilayah Dawung. Status kehadiran pada data lama: Belum Rekam Kehadiran.', 12, 1, 0, '2026-07-09 01:54:12', '2026-07-09 01:54:12', NULL),
(44, 'FADILLATUL NUR KHASANAH, S.Pd', 'PJ Jebugan', 'pemerintah', '1744664964188155.jpg', NULL, NULL, NULL, 'Pejabat penanggung jawab wilayah Jebugan. Status kehadiran pada data lama: Belum Rekam Kehadiran.', 13, 1, 0, '2026-07-09 01:54:12', '2026-07-09 01:54:12', NULL);
INSERT INTO `village_potentials` (`id`, `title`, `category`, `description`, `photo`, `is_active`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Curug Dawung', 'wisata', '<p>Air terjun alami setinggi 25 meter dengan kolam alam yang jernih, dikelilingi hutan bambu yang asri. Cocok untuk wisata keluarga.</p>', 'potentials/20260724-abc6a92fe358c3c9.png', 1, NULL, '2026-07-08 22:07:33', '2026-07-24 10:30:33', NULL),
(2, 'Persawahan Terasering', 'pertanian', '<p>Hamparan sawah terasering seluas 180 Ha yang menjadi lumbung padi desa sekaligus spot foto yang indah.</p>', 'potentials/20260724-a0e53aa330eaa21e.png', 1, NULL, '2026-07-08 22:07:33', '2026-07-24 10:30:04', NULL),
(3, 'Budidaya Ikan Nila', 'perikanan', '<p>Kolam budidaya ikan nila dan lele milik kelompok pembudidaya ikan dengan produksi rata-rata 2 ton per bulan.</p>', 'potentials/20260724-2c892da4431112d6.png', 1, NULL, '2026-07-08 22:07:33', '2026-07-24 10:28:42', NULL),
(4, 'Seni Tradisional Calung', 'budaya', '<p>Kesenian musik bambu tradisional yang masih dilestarikan sanggar seni desa dan rutin tampil di acara desa.</p>', 'potentials/20260724-5e4b22ca261373af.png', 1, NULL, '2026-07-08 22:07:33', '2026-07-24 10:28:06', NULL);
INSERT INTO `village_profiles` (`id`, `section_key`, `title`, `content`, `image`, `sort_order`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'sejarah', 'Sejarah Desa', '<div class=\"main-content print space-y-4\" style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; color: rgb(51, 65, 85); font-family: Inter, sans-serif;\"><div class=\"main-content print space-y-4\" style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ;\"><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\"><span style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; font-weight: bolder;\">DESA DAWUNG</span> Dinamakan dawung itu berasal&nbsp; dari pohon dawung ditemukan pada zaman Belanda Tahun 1933,nama Kepala desa atau pemimpin pada saat itu pertama Dawung adalah Demang. Pemerintahan pada saat itu pun hanya di isikan Demang, carik, Penewu, dan Jogo boyo,tempat&nbsp; Pohon dawung yang ada di lokasi tersebut yang sekarang tempatnya&nbsp; dibuat balai desa itu dahulu di potong oleh masyarakat untuk menghalangi sekutu jepang lewat</p><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\">Sebelum terbentuknya pemerintahan demang atau kepala desa</p><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\">Peristiwa jadi demang daerah dawung&nbsp; jaman dahulu kala wilayah disini tidak aman, Banyak Kejahatan meraja lela, banyak kejahatan seperti pencurian, kekerasan dan sebagainya, hukum yang berlaku saat itu adalah hukum rimba</p><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\">Ditahun 1916 kerajaan di jaman majapahit, adipati atau saat ini&nbsp; jabatan tersebut dinamakan bupati dan juga masyarakat, pun sepakat untuk melakukan sayembara, mengangkat pemimpin guna untuk masyarakat aman, damai dan tentram, sayembara di lakukan dengan persyaratan yang ditentukan adipati disetujui oleh masyarakat salah satunya barang&nbsp; siapa yang kuat, sakti dan bisa menangkap, memberantas kejahatan itulah yang menjadi pemimpin di desa dawung. singkat cerita demanglah yang berhasil memenangkan sayembara tersebut ,pada saat itu pemerintahan demang di bantu carik, penewu dan juga jogo boyo, berhasil memberantas kejahatan yang merajalela dan juga berhasil mengusir jepang dan sekutunya dengan peralatan seadanya seperti bambu runcing, pohon pada saat itu banyak yang ditebang salah satunya pohon dawung oleh masyarakat, guna untuk menjadikan alat menghalangi jalan sekutu jepang agar tidak bisa melewati desa dawung, alat transportasi yang di gunakan jepang adalah tank krepyak, pada saat itu masyarakat sangatlah berhati - hati dengan jepang karena jika ketangkap atau membangkang dari aturan sekutu jepang, salah satu masyarakat di sekap dan disuruh kerja romusa kerja paksa tanpa dibayar, setelah waktu yang ditentukan oleh jepang masyarakat tersebut di kembalikan kekeluarganya , akan tetapi kebanyakan dari warga setelah di sekap selang 2-3 hari warga tersebut meninggal tanpa ada sebab yang pasti.</p><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\">1933 -1983 di pimping oleh Pak darmo harjono</p><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\">Setelah di pimpin demang pada Tahun 1933, pak demang di gantikan yang sekarang menjadi nama kepala desa bernama darmo arjono, relawan pembela negara perjuangan tanpa di bayar untuk melawan jepang, kepala desa darmo arjono, pada saat itu tidak memiliki kantor pemerintahan desa , otomatis saat itu bertempat tinggal di nangsri tempat tinggal dari kepala desa darmo arjo,&nbsp; pada tahun 1972 barulah beliau pak kepala desa mempunyai ide untuk membangun kantor pemerintahan desa , bertemapat di desa dawung, pada tahun 1975 pembangunan pun selesai tapi belum di fungsikan sebagaimana mestinya, barulah tahun 1976 kantor pemerintahan desa dawung difungsikan sampai sekarang ini.</p><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\">Masyarakat dawung pada saat zaman dahulu banyak bermata pencarian petani</p><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\">Pengasilan pertama desa dawung sejak jaman dulu adalah pertanian hasil bumi, nanas yang di gunakan , oleh masyarakat dan juga belanda sebagai membuat tali tambang, baju, wadah gandum, dll,</p></div><p style=\"border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter: ; margin: 16px 0px 0px; --tw-space-y-reverse: 0;\"></p><div id=\"print\" style=\"box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter:         ; --tw-space-y-reverse: 0; margin-top: 16px; margin-bottom: 0px; color: rgb(51, 65, 85); font-family: Inter, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"></div></div><div id=\"print\" style=\"box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-transform: translateX(0) translateY(0) rotate(0) skewX(0) skewY(0) scaleX(1) scaleY(1); --tw-border-opacity: 1; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-filter:         ; --tw-space-y-reverse: 0; margin-top: 16px; margin-bottom: 0px; color: rgb(51, 65, 85); font-family: Inter, sans-serif; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"></div>', 'profile/20260709-8ab6717d46e663db.jpg', 1, 1, '2026-07-08 22:07:33', '2026-07-09 02:58:23'),
(2, 'visi', 'Visi', '<p><strong>\"Terwujudnya Desa Dawung yang Maju, Mandiri, Transparan, dan Sejahtera Berlandaskan Gotong Royong.\"</strong></p>', NULL, 2, 1, '2026-07-08 22:07:33', '2026-07-09 08:19:43'),
(3, 'misi', 'Misi', '<ul><li>Meningkatkan kualitas pelayanan administrasi publik.</li><li>Mewujudkan tata kelola pemerintahan desa yang transparan dan akuntabel.</li><li>Mengembangkan potensi ekonomi desa dan UMKM.</li><li>Meningkatkan pembangunan infrastruktur yang merata.</li><li>Melestarikan budaya dan kearifan lokal.</li></ul>', NULL, 3, NULL, '2026-07-08 22:07:33', '2026-07-08 22:07:33'),
(4, 'wilayah_administratif', 'Wilayah Administratif', '<p>Desa Dawung terdiri dari 33 dusun, dan 33 RT dengan luas wilayah ±&nbsp;<span style=\"color: rgb(230, 239, 233); font-family: Nunito, sans-serif; background-color: rgba(15, 26, 21, 0.72);\">619,34 </span>Ha yang meliputi pemukiman, persawahan, perkebunan, dan fasilitas umum.</p>', NULL, 4, 1, '2026-07-08 22:07:33', '2026-07-09 08:20:12'),
(5, 'batas_wilayah', 'Batas Wilayah', '<ul><li><strong>Utara:</strong> Desa Contoh Utara</li><li><strong>Selatan:</strong> Desa Contoh Selatan</li><li><strong>Timur:</strong> Desa Contoh Timur</li><li><strong>Barat:</strong> Desa Contoh Barat</li></ul>', NULL, 5, NULL, '2026-07-08 22:07:33', '2026-07-08 22:07:33'),
(6, 'demografi', 'Demografi Umum', '<p>Mayoritas penduduk bekerja sebagai petani, pedagang, dan wiraswasta. Komposisi penduduk relatif seimbang antara laki-laki dan perempuan dengan piramida penduduk usia produktif yang dominan.</p>', NULL, 6, NULL, '2026-07-08 22:07:33', '2026-07-08 22:07:33'),
(7, 'sarana_prasarana', 'Sarana dan Prasarana', '<ul><li>Kantor Desa dan Balai Pertemuan</li><li>2 Sekolah Dasar, 1 SMP</li><li>1 Puskesmas Pembantu, 3 Posyandu</li><li>4 Masjid, 6 Musala</li><li>Lapangan olahraga dan pasar desa</li></ul>', NULL, 7, NULL, '2026-07-08 22:07:33', '2026-07-08 22:07:33'),
(8, 'lembaga_desa', 'Lembaga Desa', '<p>BPD, LPM, PKK, Karang Taruna, Linmas, Posyandu, Kelompok Tani, dan BUMDes aktif berperan dalam pembangunan desa.</p>', NULL, 8, NULL, '2026-07-08 22:07:33', '2026-07-08 22:07:33'),
(9, 'geografis', 'Kondisi Geografis', '<p>Desa berada di ketinggian ± 191 mdpl dengan suhu rata-rata 24-30°C. Didominasi oleh perpaduan <span class=\"Yjhzub\" jsaction=\"\" jscontroller=\"zYmgkd#vvzi1e\" data-sfc-root=\"ep\" jsuid=\"XDscBe_1g\" data-sfc-cb=\"\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 700; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\" style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-weight: 700; margin: 0px; border-bottom: 0px rgb(10, 10, 10);\">dataran rendah dan perbukitan landai</span>. Karakter tanah di wilayah Sambirejo dikenal sangat <span class=\"Yjhzub\" jsaction=\"\" jscontroller=\"zYmgkd#vvzi1e\" data-sfc-root=\"ep\" jsuid=\"XDscBe_1h\" data-sfc-cb=\"\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-size: 16px; font-weight: 700; margin: 0px; text-decoration: none; border-bottom: 0px rgb(10, 10, 10);\" style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-weight: 700; margin: 0px; border-bottom: 0px rgb(10, 10, 10);\">subur</span> karena mendapat pasokan air yang baik dari sumber alam perbukitan, sehingga sangat mendukung sektor pertanian komoditas padi, perkebunan, hingga peternakan.</p>', NULL, 9, 1, '2026-07-08 22:07:33', '2026-07-09 08:22:33'),
(10, 'sosial_ekonomi', 'Kondisi Sosial Ekonomi', '<p>Perekonomian desa ditopang sektor pertanian padi dan hortikultura, peternakan, perikanan air tawar, serta UMKM kuliner. Kegiatan sosial gotong royong masih terjaga kuat.</p>', NULL, 10, 1, '2026-07-08 22:07:33', '2026-07-09 08:23:07');
